import { describe as vitestDescribe, expect, test as vitestTest } from "vitest";
export const describe = vitestDescribe;
export const test = vitestTest;
/**
 * Return the success value, or throw if the `Result` is an error.
 * Use in tests/setup when you expect success and want to fail loudly otherwise.
 * @throws Error if `r.ok` is `false`.
 */
export function assertOk(r) {
    if (r.ok === false)
        throw new Error(`Expected ok:true, but got error: ${JSON.stringify(r.error)}`);
    return r.value;
}
/**
 * Return the error, or throw if the `Result` is a success.
 * @throws Error if `r.ok` is `true`.
 */
export function assertErr(r) {
    if (r.ok === true)
        throw new Error(`Expected ok:false, but got value: ${JSON.stringify(r.value)}`);
    return r.error;
}
// Recursively relax the `error` of any error-Result so checkExpect does not
// over-fit to the exact error message. We keep `ok: false` (and everything on
// the success path, including `value`) but accept any error content. Applied to
// the *expected* value, leveraging vitest's asymmetric matchers, so it also
// handles Results nested inside values or arrays.
const relaxResultErrors = (value) => {
    if (Array.isArray(value)) {
        return value.map(relaxResultErrors);
    }
    if (value !== null && typeof value === "object") {
        const out = {};
        for (const [key, val] of Object.entries(value)) {
            out[key] = relaxResultErrors(val);
        }
        // An error-Result: require that it *is* an error, but accept any message.
        if (out.ok === false && "error" in out) {
            out.error = expect.anything();
        }
        return out;
    }
    return value;
};
// Design note for maintainers:
// These helpers return test bodies instead of registering nested tests so IDE
// test discovery (especially VS Code's Vitest extension) can match static names
// to runtime leaves. This keeps per-check run arrows reliable and reinforces
// one-check-per-test style in student code.
/**
 * Build a test body that checks equality (like BSL's check-expect).
 *
 * Use as: `test("...", checkExpect(() => expressionUnderTest, expectedValue))`
 *
 * The check validates that the expected value is equal to the actual value.
 *
 * If the expected value is a `Result` with `ok: false`, the check will
 * accept any `error` content in the actual value. The actual value must still
 * be an error-`Result`, and this applies to error-`Result`s nested inside
 * arrays or objects too. If you want to check the error content, use
 * {@link checkExpectExact}.
 *
 * @param actual thunk that computes the value to check; may be async
 * @param expected expected value (`Result` errors are relaxed for message text)
 * @returns a Vitest-compatible async test body
 */
export function checkExpect(actual, expected) {
    return async () => {
        expect(await actual()).toEqual(relaxResultErrors(expected));
    };
}
/**
 * Like {@link checkExpect}, but with no relaxation: an error-`Result` must
 * match its `error` content exactly. Use when the message is part of the
 * contract under test.
 *
 * Use as: `test("...", checkExpectExact(() => expressionUnderTest, expectedValue))`
 *
 * @param actual thunk that computes the value to check; may be async
 * @param expected expected value, compared in full
 * @returns a Vitest-compatible async test body
 */
export function checkExpectExact(actual, expected) {
    return async () => {
        expect(await actual()).toEqual(expected);
    };
}
/**
 * Build a test body that checks that an expression throws (like BSL's
 * check-error).
 *
 * Use as: `test("...", checkError(() => expressionUnderTest, "expected message"))`
 *
 * NOTE: The `error` argument is documentation only; the check confirms that
 * `actual()` throws (or rejects) and accepts *any* thrown error, so a wrong
 * message will still pass. To check the message too, use
 * {@link checkErrorExact}.
 *
 * @param actual thunk expected to throw/reject; may be async
 * @param error the expected message, recorded for readers but not enforced
 * @returns a Vitest-compatible async test body
 */
export function checkError(actual, error) {
    return async () => {
        await expect(Promise.resolve().then(actual)).rejects.toThrow();
    };
}
/**
 * Like {@link checkError}, but the message is enforced: `actual()` must throw
 * (or reject) with an error whose message contains `error`. Use when the
 * message is part of the contract under test.
 *
 * Use as: `test("...", checkErrorExact(() => expressionUnderTest, "expected message"))`
 *
 * @param actual thunk expected to throw/reject; may be async
 * @param error message (or substring) the thrown error must contain
 * @returns a Vitest-compatible async test body
 */
export function checkErrorExact(actual, error) {
    return async () => {
        await expect(Promise.resolve().then(actual)).rejects.toThrow(error);
    };
}
/**
 * A graded variant of {@link checkExpect} for instructor-authored private tests.
 *
 * Returns a Vitest test body. Use as `test("...", gradedCheck(...))`.
 * `actual` is a thunk (`() => T`) evaluated inside the test body so thrown
 * exceptions are reported as test failures with `points`/`hint` attached.
 *
 * @param actual a thunk producing the value under test
 * @param expected the value `actual()` should equal (error-Results are relaxed)
 * @param options points/hint/briefHint/difficulty recorded on `task.meta`.
 */
export function gradedCheck(actual, expected, options) {
    return async ({ task }) => {
        // Attach metadata first, so points/hint survive even if actual() throws.
        if (options) {
            Object.assign(task.meta, options);
        }
        expect(await actual()).toEqual(relaxResultErrors(expected));
    };
}
/**
 * Graded variant of {@link checkExpectExact}: no relaxation, so an
 * error-`Result` must match its `error` content exactly. Records `points`/`hint`
 * on `task.meta` like {@link gradedCheck}.
 *
 * @param actual a thunk producing the value under test
 * @param expected the value `actual()` should equal, compared in full
 * @param options points/hint/briefHint/difficulty recorded on `task.meta`.
 */
export function gradedCheckExact(actual, expected, options) {
    return async ({ task }) => {
        // Attach metadata first, so points/hint survive even if actual() throws.
        if (options) {
            Object.assign(task.meta, options);
        }
        expect(await actual()).toEqual(expected);
    };
}
/**
 * A graded variant of {@link checkError} for instructor-authored private tests.
 *
 * Returns a Vitest test body. Use as `test("...", gradedError(...))`. The
 * `actual` thunk is expected to throw, and `points`/`hint` are recorded whether
 * or not it throws as expected. The companion to {@link gradedCheck}.
 *
 * As in {@link checkError}, `error` is documentation only: any thrown message
 * is accepted.
 *
 * @param actual a thunk expected to throw
 * @param error the expected message, recorded for readers but not enforced
 * @param options points/hint/briefHint/difficulty recorded on `task.meta`.
 */
export function gradedError(actual, error, options) {
    return async ({ task }) => {
        // Attach metadata first, so points/hint survive however the assertion goes.
        if (options) {
            Object.assign(task.meta, options);
        }
        await expect(Promise.resolve().then(actual)).rejects.toThrow();
    };
}
/**
 * Graded variant of {@link checkErrorExact}: the thrown error's message must
 * contain `error`. Records `points`/`hint` on `task.meta` like
 * {@link gradedError}.
 *
 * @param actual a thunk expected to throw
 * @param error message (or substring) the thrown error must contain
 * @param options points/hint/briefHint/difficulty recorded on `task.meta`.
 */
export function gradedErrorExact(actual, error, options) {
    return async ({ task }) => {
        // Attach metadata first, so points/hint survive however the assertion goes.
        if (options) {
            Object.assign(task.meta, options);
        }
        await expect(Promise.resolve().then(actual)).rejects.toThrow(error);
    };
}
